Here is the commit message:
netfilter: nf_queue: hold bridge skb->dev while queued

br_pass_frame_up() rewrites skb->dev from the ingress port to the bridge
master before queueing bridge LOCAL_IN packets. NFQUEUE only holds
references on state.in/out and bridge physdevs, so a queued bridge
packet can retain a freed bridge master in skb->dev until reinjection.

When the verdict is reinjected later, br_netif_receive_skb() re-enters
the receive path with skb->dev still pointing at the freed bridge master,
triggering a use-after-free.

Store skb->dev in the queue entry, hold a reference on it for the queue
lifetime, and use the saved device when dropping queued packets during
NETDEV_DOWN handling.

Fixes: ac2863445686 ("netfilter: bridge: add nf_afinfo to enable queuing to userspace")
Cc: stable@kernel.org
Reported-by: Yuan Tan <yuantan098@gmail.com>
Reported-by: Yifan Wu <yifanwucs@gmail.com>
Reported-by: Juefei Pu <tomapufckgml@gmail.com>
Reported-by: Xin Liu <bird@lzu.edu.cn>
Signed-off-by: Haoze Xie <royenheart@gmail.com>
Signed-off-by: Ren Wei <n05ec@lzu.edu.cn>
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>

Here is the root cause:
The nf_queue entry does not save and hold a reference to skb->dev at the time of queueing. When br_pass_frame_up() changes skb->dev from the ingress port to the bridge master before queueing bridge LOCAL_IN packets, the queued packet retains a pointer to the bridge master in skb->dev. Since the queue entry only holds references on state.in/out and bridge physdevs, the bridge master can be freed (e.g., during NETDEV_DOWN) while the entry is still queued. Upon reinjection, br_netif_receive_skb() uses the dangling skb->dev, causing a use-after-free.

Here is the patch:

 static void nf_queue_entry_release_refs(struct nf_queue_entry *entry)
 {
 	struct nf_hook_state *state = &entry->state;

 	/* Release those devices we held, or Alexey will kill me. */
+	dev_put(entry->skb_dev);
 	dev_put(state->in);
 	dev_put(state->out);
 	if (state->sk)
 		nf_queue_sock_put(state->sk);

 #if IS_ENABLED(CONFIG_BRIDGE_NETFILTER)
 	dev_put(entry->physin);
 	dev_put(entry->physout);
 #endif
 }

 /* Bump dev refs so they don't vanish while packet is out */
 bool nf_queue_entry_get_refs(struct nf_queue_entry *entry)
 {
 	struct nf_hook_state *state = &entry->state;

 	if (state->sk && !refcount_inc_not_zero(&state->sk->sk_refcnt))
 		return false;

+	dev_hold(entry->skb_dev);
 	dev_hold(state->in);
 	dev_hold(state->out);

 #if IS_ENABLED(CONFIG_BRIDGE_NETFILTER)
 	dev_hold(entry->physin);
 	dev_hold(entry->physout);
 #endif
 	return true;
 }
 EXPORT_SYMBOL_GPL(nf_queue_entry_get_refs);

 static int __nf_queue(struct sk_buff *skb, const struct nf_hook_state *state,
 		      unsigned int index, unsigned int queuenum)
 {
 	struct nf_queue_entry *entry = NULL;
 	const struct nf_queue_handler *qh;
 	unsigned int route_key_size;
 	int status;

 	/* QUEUE == DROP if no one is waiting, to be safe. */
 	qh = rcu_dereference(nf_queue_handler);
 	if (!qh)
 		return -ESRCH;

 	switch (state->pf) {
 	case AF_INET:
 		route_key_size = sizeof(struct ip_rt_info);
 		break;
 	case AF_INET6:
 		route_key_size = sizeof(struct ip6_rt_info);
 		break;
 	default:
 		route_key_size = 0;
 		break;
 	}

 	if (skb_sk_is_prefetched(skb)) {
 		struct sock *sk = skb->sk;

 		if (!sk_is_refcounted(sk)) {
 			if (!refcount_inc_not_zero(&sk->sk_refcnt))
 				return -ENOTCONN;

 			/* drop refcount on skb_orphan */
 			skb->destructor = sock_edemux;
 		}
 	}

 	entry = kmalloc(sizeof(*entry) + route_key_size, GFP_ATOMIC);
 	if (!entry)
 		return -ENOMEM;

 	if (skb_dst(skb) && !skb_dst_force(skb)) {
 		kfree(entry);
 		return -ENETDOWN;
 	}

 	*entry = (struct nf_queue_entry) {
 		.skb	= skb,
+		.skb_dev = skb->dev,
 		.state	= *state,
 		.hook_index = index,
 		.size	= sizeof(*entry) + route_key_size,
 	};
-
 	__nf_queue_entry_init_physdevs(entry);

 	if (!nf_queue_entry_get_refs(entry)) {
 		kfree(entry);
 		return -ENOTCONN;
 	}

 	switch (entry->state.pf) {
 	case AF_INET:
 		nf_ip_saveroute(skb, entry);
 		break;
 	case AF_INET6:
 		nf_ip6_saveroute(skb, entry);
 		break;
 	}

 	status = qh->outfn(entry, queuenum);
 	if (status < 0) {
 		nf_queue_entry_free(entry);
 		return status;
 	}

 	return 0;
 }



